          "code": "import numpy as np\nfrom scipy.optimize import minimize\nfrom scipy.special import expit\n\nrng = np.random.default_rng(7)\nn = 300\nx1 = rng.normal(0.0, 1.0, size=n)\nx2 = rng.binomial(1, 0.12, size=n).astype(float)\nX = np.column_stack([np.ones(n), x1, x2])\n\ndef fit_mle_and_wald(X_mat, y_vec, lam=0.0):\n    def obj(w):\n        z = X_mat @ w\n        return float(np.sum(np.logaddexp(0.0, z) - y_vec * z) + 0.5 * lam * np.dot(w[1:], w[1:]))\n    def grad(w):\n        p = expit(X_mat @ w)\n        g = X_mat.T @ (p - y_vec)\n        g[1:] += lam * w[1:]\n        return g\n    res = minimize(obj, np.zeros(X_mat.shape[1]), jac=grad, method=\"BFGS\", options={\"gtol\": 1e-8})\n    w_hat = res.x\n    p_hat = expit(X_mat @ w_hat)\n    W_diag = p_hat * (1.0 - p_hat)\n    # Matriks Fisher Information I(w) = X^T W X + lam * diag(0, 1, 1)\n    reg_mat = np.diag([0.0] + [lam] * (X_mat.shape[1] - 1))\n    fisher = (X_mat.T * W_diag) @ X_mat + reg_mat\n    cov = np.linalg.pinv(fisher)\n    se = np.sqrt(np.maximum(np.diag(cov), 1e-18))\n    wald_z = w_hat / se\n    return w_hat, se, wald_z, float(np.min(W_diag))\n\n# Bangkitkan label lalu perkuat pemisahan fitur biner x2 hingga quasi-complete separation\ny_base = (rng.uniform(0, 1, size=n) < expit(-1.2 + 0.8 * x1 + 1.5 * x2)).astype(float)\ny_quasi = y_base.copy()\nidx_x2 = np.where(x2 == 1.0)[0]\n\nprint(\"=== Audit Efek Hauck-Donner: Keruntuhan Statistik Wald Menuju Complete Separation ===\")\nprint(\"Skenario                       | beta_x2  | SE(beta_x2) | Wald z   | min p(1-p)\")\nprint(\"-\" * 80)\nfor label, frac_pos, lam_val in [\n    (\"Normal (campuran, lam=0)      \", 0.70, 0.0),\n    (\"Nyaris Pisah (97% pos, lam=0) \", 0.97, 0.0),\n    (\"Quasi-Separated (100%, lam=0) \", 1.00, 0.0),\n    (\"Quasi-Separated (100%, L2=1.0)\", 1.00, 1.0),\n]:\n    y_cur = y_base.copy()\n    n_pos = int(round(frac_pos * len(idx_x2)))\n    y_cur[idx_x2] = 0.0\n    y_cur[idx_x2[:n_pos]] = 1.0\n    w_h, se_h, z_h, min_w = fit_mle_and_wald(X, y_cur, lam=lam_val)\n    print(f\"{label} | {w_h[2]:+8.3f} | {se_h[2]:11.3f} | {z_h[2]:+8.3f} | {min_w:.3e}\")",
