          "filename": "08_2_irls_cholesky_vs_gd.py",
          "code": "import numpy as np\nfrom scipy.linalg import cho_factor, cho_solve\n\nrng = np.random.default_rng(42)\nn, d = 800, 12\nX_raw = rng.normal(0.0, 1.0, size=(n, d))\n# Beri skala heterogen sedang agar GD melambat sementara Newton/IRLS tetap invarian\nscales = np.geomspace(0.3, 6.0, d)\nX_feat = X_raw * scales\nX = np.column_stack([np.ones(n), X_feat])  # kolom 0 = intercept\nw_true = np.concatenate([[ -0.4 ], rng.normal(0.0, 0.6, size=d) / scales])\ny = (rng.uniform(0, 1, size=n) < 1.0 / (1.0 + np.exp(-(X @ w_true)))).astype(float)\n\nlam = 1.0  # penalti L2 (tidak diterapkan pada intercept)\nreg_diag = np.array([0.0] + [lam] * d)\n\ndef sigmoid(z):\n    return np.where(z >= 0, 1.0 / (1.0 + np.exp(-z)), np.exp(z) / (1.0 + np.exp(z)))\n\ndef obj_fn(w):\n    z = X @ w\n    return float(np.sum(np.logaddexp(0.0, z) - y * z) + 0.5 * lam * np.dot(w[1:], w[1:]))\n\ndef grad_fn(w):\n    p = sigmoid(X @ w)\n    return X.T @ (p - y) + reg_diag * w\n\n# 1) IRLS / Damped Newton-Raphson dengan Cholesky & Armijo Backtracking\nw_irls = np.zeros(d + 1)\nprint(\"=== Konvergensi Kuadratik IRLS (Newton-Raphson + Cholesky) ===\")\nfor it in range(1, 15):\n    z = X @ w_irls\n    p = sigmoid(z)\n    W = np.clip(p * (1.0 - p), 1e-12, 0.25)\n    g = X.T @ (p - y) + reg_diag * w_irls\n    gnorm = float(np.linalg.norm(g))\n    print(f\"  IRLS iter {it:2d} | Obj={obj_fn(w_irls):10.6f} | ||grad||_2={gnorm:.3e}\")\n    if gnorm < 1e-10:\n        break\n    H = (X.T * W) @ X + np.diag(reg_diag)\n    c_fac = cho_factor(H)\n    delta = cho_solve(c_fac, -g)  # solusi H * delta = -g tanpa inversi eksplisit\n    # Armijo backtracking line search\n    alpha = 1.0\n    f0 = obj_fn(w_irls)\n    slope = float(np.dot(g, delta))\n    while obj_fn(w_irls + alpha * delta) > f0 + 1e-4 * alpha * slope:\n        alpha *= 0.5\n    w_irls = w_irls + alpha * delta\n\n# 2) Bandingkan dengan Gradient Descent Orde-1 memakai step size optimal 1/L\nL_bound = float(0.25 * np.linalg.eigvalsh(X.T @ X)[-1] + lam)\neta = 1.0 / L_bound\nw_gd = np.zeros(d + 1)\nfor it in range(1, 501):\n    w_gd = w_gd - eta * grad_fn(w_gd)\ngd_gnorm = float(np.linalg.norm(grad_fn(w_gd)))\nprint(f\"=== Pembanding Gradient Descent (step=1/L={eta:.2e}) setelah 500 iterasi ===\")\nprint(f\"  GD iter 500  | Obj={obj_fn(w_gd):10.6f} | ||grad||_2={gd_gnorm:.3e}\")\nprint(f\"  Selisih ||w_irls - w_gd||_2 = {np.linalg.norm(w_irls - w_gd):.3e}\")",
          "expectedOutput": "=== Konvergensi Kuadratik IRLS (Newton-Raphson + Cholesky) ===\n  IRLS iter  1 | Obj=554.517744 | ||grad||_2=7.412e+02\n  IRLS iter  2 | Obj=374.044180 | ||grad||_2=1.657e+02\n  IRLS iter  3 | Obj=353.256509 | ||grad||_2=3.734e+01\n  IRLS iter  4 | Obj=351.581220 | ||grad||_2=3.513e+00\n  IRLS iter  5 | Obj=351.564217 | ||grad||_2=3.934e-02\n  IRLS iter  6 | Obj=351.564215 | ||grad||_2=5.030e-06\n  IRLS iter  7 | Obj=351.564215 | ||grad||_2=1.312e-13\n=== Pembanding Gradient Descent (step=1/L=1.28e-04) setelah 500 iterasi ===\n  GD iter 500  | Obj=353.036989 | ||grad||_2=7.575e+00\n  Selisih ||w_irls - w_gd||_2 = 4.036e-01",
