          "code": "import numpy as np\nfrom scipy import sparse\nfrom sklearn.datasets import make_classification\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import log_loss\nfrom sklearn.preprocessing import StandardScaler\n\n# 1) Rezim Dense (N=1500, d=40): bandingkan lbfgs, newton-cholesky, newton-cg, saga\nX_d, y_d = make_classification(\n    n_samples=1500, n_features=40, n_informative=18, n_redundant=6,\n    random_state=42\n)\nX_d = StandardScaler().fit_transform(X_d)\n\nprint(\"=== Benchmark Solver Scikit-Learn 1.9 pada Matriks Dense (N=1500, d=40, L2 C=1.0) ===\")\nref_coef = None\nfor solver_name in (\"newton-cholesky\", \"lbfgs\", \"newton-cg\", \"saga\"):\n    clf = LogisticRegression(solver=solver_name, C=1.0, tol=1e-6, max_iter=1000, random_state=42)\n    clf.fit(X_d, y_d)\n    ll = log_loss(y_d, clf.predict_proba(X_d)[:, 1])\n    if ref_coef is None:\n        ref_coef = clf.coef_[0]\n    diff = float(np.linalg.norm(clf.coef_[0] - ref_coef))\n    print(f\"  solver={solver_name:16s} | n_iter={int(clf.n_iter_[0]):3d} | train_logloss={ll:.6f} | ||dw||={diff:.2e}\")\n\n# 2) Rezim High-Dim Sparse (N=1200, d=2500, density=3%): L2 (lbfgs vs saga) & L1 sparse (saga)\nrng = np.random.default_rng(42)\nX_sp = sparse.random(1200, 2500, density=0.03, format=\"csr\", random_state=42, data_rvs=rng.standard_normal)\nw_sparse_true = np.zeros(2500)\nw_sparse_true[:25] = rng.normal(0.0, 1.5, size=25)  # hanya 25 fitur sinyal sejati\nlogits_sp = X_sp @ w_sparse_true\ny_sp = (rng.uniform(0, 1, size=1200) < 1.0 / (1.0 + np.exp(-logits_sp))).astype(int)\n\nprint(\"=== Rezim High-Dim Sparse (N=1200, d=2500, 3% non-zero) ===\")\nclf_lbfgs_sp = LogisticRegression(solver=\"lbfgs\", C=0.5, max_iter=500).fit(X_sp, y_sp)\nclf_saga_l2 = LogisticRegression(solver=\"saga\", C=0.5, l1_ratio=0.0, max_iter=500, random_state=42).fit(X_sp, y_sp)\nclf_saga_l1 = LogisticRegression(solver=\"saga\", C=0.5, l1_ratio=1.0, max_iter=500, random_state=42).fit(X_sp, y_sp)\n\nfor label, m in [\n    (\"lbfgs (L2)     \", clf_lbfgs_sp),\n    (\"saga  (L2)     \", clf_saga_l2),\n    (\"saga  (L1=1.0) \", clf_saga_l1),\n]:\n    nnz = int(np.sum(np.abs(m.coef_[0]) > 1e-8))\n    ll = log_loss(y_sp, m.predict_proba(X_sp)[:, 1])\n    print(f\"  {label} | n_iter={int(m.n_iter_[0]):3d} | logloss={ll:.5f} | fitur_aktif(nnz)={nnz:4d}/2500\")",
          "expectedOutput": "=== Benchmark Solver Scikit-Learn 1.9 pada Matriks Dense (N=1500, d=40, L2 C=1.0) ===\n  solver=newton-cholesky  | n_iter=  5 | train_logloss=0.421525 | ||dw||=0.00e+00\n  solver=lbfgs            | n_iter= 16 | train_logloss=0.421525 | ||dw||=2.67e-05\n  solver=newton-cg        | n_iter=  7 | train_logloss=0.421525 | ||dw||=3.00e-07\n  solver=saga             | n_iter= 29 | train_logloss=0.421525 | ||dw||=7.74e-07\n=== Rezim High-Dim Sparse (N=1200, d=2500, 3% non-zero) ===\n  lbfgs (L2)      | n_iter= 13 | logloss=0.10083 | fitur_aktif(nnz)=2500/2500\n  saga  (L2)      | n_iter=106 | logloss=0.10076 | fitur_aktif(nnz)=2500/2500\n  saga  (L1=1.0)  | n_iter=304 | logloss=0.28253 | fitur_aktif(nnz)= 516/2500",
