          "filename": "08_2_hessian_cov_ram_audit.py",
          "code": "import numpy as np\nfrom scipy.linalg import cho_factor, cho_solve\n\nrng = np.random.default_rng(99)\nn, d = 600, 5\n# Buat dua fitur berkorelasi sangat kuat (r ~ 0.98) untuk menguji kurvatur Hessian\nbase = rng.normal(0.0, 1.0, size=n)\nX_raw = np.column_stack([\n    base,\n    base + rng.normal(0.0, 0.15, size=n),\n    rng.normal(0.0, 1.0, size=n),\n    rng.normal(0.0, 1.0, size=n),\n    rng.normal(0.0, 1.0, size=n),\n])\nX = np.column_stack([np.ones(n), X_raw])\nw_true = np.array([-0.2, 1.1, -0.5, 0.9, -0.7, 0.0])\np_gen = 1.0 / (1.0 + np.exp(-(X @ w_true)))\ny = (rng.uniform(0, 1, size=n) < p_gen).astype(float)\n\ndef irls_audit(lam):\n    w = np.zeros(d + 1)\n    reg = np.array([0.0] + [lam] * d)\n    for _ in range(25):\n        p = 1.0 / (1.0 + np.exp(-np.clip(X @ w, -30, 30)))\n        W = np.clip(p * (1.0 - p), 1e-12, 0.25)\n        g = X.T @ (p - y) + reg * w\n        H = (X.T * W) @ X + np.diag(reg)\n        if np.linalg.norm(g) < 1e-10:\n            break\n        w -= cho_solve(cho_factor(H), g)\n    eigs = np.linalg.eigvalsh(H)\n    cov = cho_solve(cho_factor(H), np.eye(d + 1))\n    se = np.sqrt(np.diag(cov))\n    return w, se, float(eigs[0]), float(eigs[-1]), float(eigs[-1] / eigs[0]), float(np.mean(W))\n\nprint(\"=== Diagnostik Spektrum Hessian & Standard Error Asimtotik IRLS ===\")\nfor lam_val in (1e-4, 1.0, 10.0):\n    w_h, se_h, emin, emax, kappa, w_mean = irls_audit(lam_val)\n    print(f\"lam={lam_val:6.4f} | eig_min={emin:7.3f} | eig_max={emax:7.2f} | kappa={kappa:7.2f} | mean(W_ii)={w_mean:.4f}\")\n    print(f\"           | beta_1={w_h[1]:+.3f}+/-{se_h[1]:.3f} (korr) | beta_2={w_h[2]:+.3f}+/-{se_h[2]:.3f} (korr) | beta_3={w_h[3]:+.3f}+/-{se_h[3]:.3f}\")\n\n# Audit Jejak RAM Hessian Penuh vs Riwayat L-BFGS (m=10) dalam FP64\nprint(\"=== Anggaran Memori RAM: Full Hessian O(d^2) vs L-BFGS O(2*m*d) (FP64, m=10) ===\")\nfor dim in (100, 2_000, 20_000, 120_000):\n    hess_mb = (dim * dim * 8) / (1024 ** 2)\n    lbfgs_mb = (2 * 10 * dim * 8) / (1024 ** 2)\n    print(f\"  d={dim:7,d} | Hessian={hess_mb:10.2f} MB | L-BFGS(m=10)={lbfgs_mb:6.3f} MB | Penghematan={hess_mb/lbfgs_mb:8.1f}x\")",
          "expectedOutput": "=== Diagnostik Spektrum Hessian & Standard Error Asimtotik IRLS ===\nlam=0.0001 | eig_min=  1.181 | eig_max= 223.84 | kappa= 189.56 | mean(W_ii)=0.1885\n           | beta_1=+1.527+/-0.659 (korr) | beta_2=-0.837+/-0.646 (korr) | beta_3=+0.904+/-0.111\nlam=1.0000 | eig_min=  2.203 | eig_max= 226.97 | kappa= 103.01 | mean(W_ii)=0.1903\n           | beta_1=+0.976+/-0.483 (korr) | beta_2=-0.302+/-0.475 (korr) | beta_3=+0.886+/-0.109\nlam=10.0000 | eig_min= 11.259 | eig_max= 244.92 | kappa=  21.75 | mean(W_ii)=0.1979\n           | beta_1=+0.430+/-0.217 (korr) | beta_2=+0.185+/-0.215 (korr) | beta_3=+0.790+/-0.099\n=== Anggaran Memori RAM: Full Hessian O(d^2) vs L-BFGS O(2*m*d) (FP64, m=10) ===\n  d=    100 | Hessian=      0.08 MB | L-BFGS(m=10)= 0.015 MB | Penghematan=     5.0x\n  d=  2,000 | Hessian=     30.52 MB | L-BFGS(m=10)= 0.305 MB | Penghematan=   100.0x\n  d= 20,000 | Hessian=   3051.76 MB | L-BFGS(m=10)= 3.052 MB | Penghematan=  1000.0x\n  d=120,000 | Hessian= 109863.28 MB | L-BFGS(m=10)=18.311 MB | Penghematan=  6000.0x",
