          "id": "code-ml-08-3-ch08_3_scratch",
          "title": "First-Principles: Overflow Naive Softmax, LSE Stabil & Identifiability L2",
          "language": "python",
          "filename": "08_3_softmax_lse_identifiability.py",
          "code": "import numpy as np\nfrom scipy.optimize import minimize\n\n# 1) Bukti overflow Naive Softmax vs kestabilan Log-Sum-Exp (LSE)\nz_extreme = np.array([1000.0, 1001.5, 999.2])\nwith np.errstate(over=\"ignore\", invalid=\"ignore\"):\n    naive_p = np.exp(z_extreme) / np.sum(np.exp(z_extreme))\n\ndef log_softmax_stable(Z):\n    m = np.max(Z, axis=-1, keepdims=True)\n    shifted = Z - m\n    lse = m + np.log(np.sum(np.exp(shifted), axis=-1, keepdims=True))\n    return Z - lse\n\nlog_p = log_softmax_stable(z_extreme)\nstable_p = np.exp(log_p)\n# Uji Translation Invariance: z + c memberi probabilitas identik\nstable_p_shifted = np.exp(log_softmax_stable(z_extreme - 5000.0))\n\nprint(\"=== 1. Stabilitas Numerik & Translation Invariance Softmax ===\")\nprint(f\"Naive Softmax([1000, 1001.5, 999.2])  : {naive_p}\")\nprint(f\"Stable LSE Softmax                    : {np.round(stable_p, 6)}\")\nprint(f\"Max selisih setelah geser -5000.0     : {np.max(np.abs(stable_p - stable_p_shifted)):.2e}\")\n\n# 2) Latih Softmax Multinomial dari nol (L2) & verifikasi sum-to-zero identifiability\nrng = np.random.default_rng(42)\nn, d, K = 600, 5, 4\nX = rng.normal(0.0, 1.0, size=(n, d))\nW_true = rng.normal(0.0, 1.2, size=(d, K))\nb_true = np.array([0.4, -0.3, 0.1, -0.2])\nprobs_true = np.exp(log_softmax_stable(X @ W_true + b_true))\ny = np.array([rng.choice(K, p=probs_true[i]) for i in range(n)])\nY_oh = np.eye(K)[y]\nlam = 0.5\n\ndef softmax_obj_grad(theta):\n    W = theta[: d * K].reshape(d, K)\n    b = theta[d * K :]\n    Z = X @ W + b\n    log_P = log_softmax_stable(Z)\n    P = np.exp(log_P)\n    loss = -np.mean(np.sum(Y_oh * log_P, axis=1)) + 0.5 * lam * np.sum(W * W) / n\n    diff = (P - Y_oh) / n\n    gW = X.T @ diff + (lam / n) * W\n    gb = np.sum(diff, axis=0)\n    return float(loss), np.concatenate([gW.ravel(), gb])\n\nres = minimize(softmax_obj_grad, np.zeros(d * K + K), jac=True, method=\"L-BFGS-B\", tol=1e-10)\nW_hat = res.x[: d * K].reshape(d, K)\nb_hat = res.x[d * K :]\nsum_across_k = np.sum(W_hat, axis=1)\n\nprint(\"=== 2. Identifiability Softmax L2 (Symmetry Sum-to-Zero) ===\")\nprint(f\"Konvergen dalam {res.nit} iterasi | Final Loss = {res.fun:.6f}\")\nprint(f\"Max |sum_k W_hat[j, k]| di semua fitur: {np.max(np.abs(sum_across_k)):.3e} (teoretis = 0.0!)\")\nprint(f\"Rata-rata ||W_hat[:, k]||_2 per kelas : {np.round(np.linalg.norm(W_hat, axis=0), 4)}\")",
          "expectedOutput": "=== 1. Stabilitas Numerik & Translation Invariance Softmax ===\nNaive Softmax([1000, 1001.5, 999.2])  : [nan nan nan]\nStable LSE Softmax                    : [0.168605 0.755636 0.075759]\nMax selisih setelah geser -5000.0     : 1.72e-14\n=== 2. Identifiability Softmax L2 (Symmetry Sum-to-Zero) ===\nKonvergen dalam 21 iterasi | Final Loss = 0.575104\nMax |sum_k W_hat[j, k]| di semua fitur: 1.776e-15 (teoretis = 0.0!)\nRata-rata ||W_hat[:, k]||_2 per kelas : [1.6771 1.5918 3.0958 3.6867]",
          "actualOutput": "=== 1. Stabilitas Numerik & Translation Invariance Softmax ===\nNaive Softmax([1000, 1001.5, 999.2])  : [nan nan nan]\nStable LSE Softmax                    : [0.168605 0.755636 0.075759]\nMax selisih setelah geser -5000.0     : 1.72e-14\n=== 2. Identifiability Softmax L2 (Symmetry Sum-to-Zero) ===\nKonvergen dalam 21 iterasi | Final Loss = 0.575104\nMax |sum_k W_hat[j, k]| di semua fitur: 1.776e-15 (teoretis = 0.0!)\nRata-rata ||W_hat[:, k]||_2 per kelas : [1.6771 1.5918 3.0958 3.6867]",
