          "code": "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(42)\nn, d = 1600, 6\nX = rng.normal(0.0, 1.0, size=(n, d))\nw_true = np.array([1.2, -0.9, 0.8, -0.6, 0.4, -0.3])\n# Atur intercept agar prevalensi positif aktual ~ 3.5% (data langka)\nlogits = -4.2 + X @ w_true\ny = (rng.uniform(0, 1, size=n) < 1.0 / (1.0 + np.exp(-logits))).astype(int)\n\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.35, stratify=y, random_state=42)\nsc = StandardScaler().fit(X_tr)\nX_tr_s, X_te_s = sc.transform(X_tr), sc.transform(X_te)\n\npi_true = float(np.mean(y_tr))\ntheoretical_shift = float(np.log((1.0 - pi_true) / pi_true))\n\n# Model 1: Unweighted (distribusi asli)\nm_orig = LogisticRegression(C=10.0, solver=\"lbfgs\").fit(X_tr_s, y_tr)\np_orig = m_orig.predict_proba(X_te_s)[:, 1]\n\n# Model 2: class_weight=\"balanced\" (mendorong prevalensi efektif ke 50%)\nm_bal = LogisticRegression(C=10.0, class_weight=\"balanced\", solver=\"lbfgs\").fit(X_tr_s, y_tr)\np_bal = m_bal.predict_proba(X_te_s)[:, 1]\n\n# Koreksi Prior Shift (King-Zeng / Bayes Offset) di ruang logit\ndef recalibrate_prior_shift(p_biased, pi_orig, pi_eff=0.5):\n    p_clip = np.clip(p_biased, 1e-12, 1.0 - 1e-12)\n    logit_b = np.log(p_clip / (1.0 - p_clip))\n    offset = np.log((pi_eff / (1.0 - pi_eff)) / (pi_orig / (1.0 - pi_orig)))\n    logit_cal = logit_b - offset\n    return 1.0 / (1.0 + np.exp(-logit_cal))\n\np_recal = recalibrate_prior_shift(p_bal, pi_orig=pi_true, pi_eff=0.5)\nobserved_shift = float(m_bal.intercept_[0] - m_orig.intercept_[0])\n\nprint(\"=== Audit Distorsi Intercept & Probabilitas akibat class_weight='balanced' ===\")\nprint(f\"Prevalensi Latih Asli pi_true     : {pi_true:.4f} ({int(y_tr.sum())}/{len(y_tr)} positif)\")\nprint(f\"Pergeseran Intercept Teoretis     : +{theoretical_shift:.4f}\")\nprint(f\"Pergeseran Intercept Teramati     : +{observed_shift:.4f}\")\nprint(\"Model                  | Mean(p) | AUROC  | LogLoss | Brier\")\nprint(\"-\" * 62)\nfor name, p_hat in [\n    (\"Unweighted (Asli)     \", p_orig),\n    (\"Balanced (Bias Mentah)\", p_bal),\n    (\"Balanced + King-Zeng  \", p_recal),\n]:\n    print(f\"{name} | {np.mean(p_hat):.4f}  | {roc_auc_score(y_te, p_hat):.4f} | {log_loss(y_te, p_hat):.4f}  | {brier_score_loss(y_te, p_hat):.4f}\")",
