          "code": "import numpy as np\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score, f1_score, hamming_loss\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.multioutput import ClassifierChain, MultiOutputClassifier\nfrom sklearn.preprocessing import StandardScaler\n\nrng = np.random.default_rng(42)\nn, d = 1400, 8\nX = rng.normal(0.0, 1.0, size=(n, d))\n\n# Bangkitkan 4 label multi-label dengan dependensi berantai kuat antar label\n# (misal: komorbiditas klinis di mana y2 sangat dipicu y1, dan y3 dipicu y1 & y2)\ndef sig(z):\n    return 1.0 / (1.0 + np.exp(-z))\n\nz1 = -0.3 + 1.4 * X[:, 0] - 1.1 * X[:, 1]\ny1 = (rng.uniform(0, 1, size=n) < sig(z1)).astype(int)\n\nz2 = -1.6 + 0.6 * X[:, 2] + 3.2 * y1\ny2 = (rng.uniform(0, 1, size=n) < sig(z2)).astype(int)\n\nz3 = -2.2 + 0.5 * X[:, 3] + 2.4 * y1 + 2.5 * y2\ny3 = (rng.uniform(0, 1, size=n) < sig(z3)).astype(int)\n\nz4 = -1.1 + 0.8 * X[:, 4] - 2.3 * y2 + 1.9 * y3\ny4 = (rng.uniform(0, 1, size=n) < sig(z4)).astype(int)\n\nY = np.column_stack([y1, y2, y3, y4])\nX_tr, X_te, Y_tr, Y_te = train_test_split(X, Y, test_size=0.30, random_state=42)\nsc = StandardScaler().fit(X_tr)\nX_tr_s, X_te_s = sc.transform(X_tr), sc.transform(X_te)\n\nbase_lr = LogisticRegression(C=1.0, solver=\"lbfgs\", max_iter=500)\n\n# 1) Binary Relevance (4 klasifikator independen)\nbr = MultiOutputClassifier(base_lr).fit(X_tr_s, Y_tr)\nY_pred_br = br.predict(X_te_s)\n\n# 2) Classifier Chain (urutan natural 0 -> 1 -> 2 -> 3)\ncc = ClassifierChain(base_lr, order=[0, 1, 2, 3], random_state=42).fit(X_tr_s, Y_tr)\nY_pred_cc = cc.predict(X_te_s).astype(int)\n\n# 3) Ensemble of Classifier Chains (ECC) dengan 5 permutasi urutan acak\norders = [[0, 1, 2, 3], [1, 2, 3, 0], [2, 0, 1, 3], [3, 2, 1, 0], [0, 2, 1, 3]]\necc_probs = np.mean([\n    ClassifierChain(base_lr, order=ord_i, random_state=42).fit(X_tr_s, Y_tr).predict_proba(X_te_s)\n    for ord_i in orders\n], axis=0)\nY_pred_ecc = (ecc_probs >= 0.5).astype(int)\n\nprint(\"=== Perbandingan Multi-Label: Binary Relevance vs Classifier Chain vs ECC ===\")\nprint(\"Metode                 | ExactMatch | HammingLoss | Micro-F1 | Macro-F1\")\nprint(\"-\" * 73)\nfor name, Yp in [\n    (\"Binary Relevance (BR) \", Y_pred_br),\n    (\"Classifier Chain (CC) \", Y_pred_cc),\n    (\"Ensemble CC (5 order) \", Y_pred_ecc),\n]:\n    em = accuracy_score(Y_te, Yp)\n    hl = hamming_loss(Y_te, Yp)\n    mif = f1_score(Y_te, Yp, average=\"micro\")\n    maf = f1_score(Y_te, Yp, average=\"macro\")\n    print(f\"{name} | {em:10.4f} | {hl:11.4f} | {mif:8.4f} | {maf:8.4f}\")",
          "expectedOutput": "=== Perbandingan Multi-Label: Binary Relevance vs Classifier Chain vs ECC ===\nMetode                 | ExactMatch | HammingLoss | Micro-F1 | Macro-F1\n-------------------------------------------------------------------------\nBinary Relevance (BR)  |     0.4048 |      0.2673 |   0.6489 |   0.5583\nClassifier Chain (CC)  |     0.4405 |      0.2786 |   0.6256 |   0.5325\nEnsemble CC (5 order)  |     0.4333 |      0.2726 |   0.6388 |   0.5425",
          "actualOutput": "=== Perbandingan Multi-Label: Binary Relevance vs Classifier Chain vs ECC ===\nMetode                 | ExactMatch | HammingLoss | Micro-F1 | Macro-F1\n-------------------------------------------------------------------------\nBinary Relevance (BR)  |     0.4048 |      0.2673 |   0.6489 |   0.5583\nClassifier Chain (CC)  |     0.4405 |      0.2786 |   0.6256 |   0.5325\nEnsemble CC (5 order)  |     0.4333 |      0.2726 |   0.6388 |   0.5425",
